export const getGetEvidenceUrl = (params?: GetEvidenceParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/evidence?${stringifiedParams}` : `/api/evidence`
}

/**
 * @summary List all evidence items (Beweismittel)
 */
export const getEvidence = async (params?: GetEvidenceParams, options?: RequestInit): Promise<Evidence[]> => {

  return customFetch<Evidence[]>(getGetEvidenceUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetEvidenceQueryKey = (params?: GetEvidenceParams,) => {
    return [
    `/api/evidence`, ...(params ? [params] : [])
    ] as const;
    }


export const getGetEvidenceQueryOptions = <TData = Awaited<ReturnType<typeof getEvidence>>, TError = ErrorType<unknown>>(params?: GetEvidenceParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getEvidence>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetEvidenceQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getEvidence>>> = ({ signal }) => getEvidence(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getEvidence>>, TError, TData> & { queryKey: QueryKey }
}

export type GetEvidenceQueryResult = NonNullable<Awaited<ReturnType<typeof getEvidence>>>
export type GetEvidenceQueryError = ErrorType<unknown>


/**
 * @summary List all evidence items (Beweismittel)
 */

export function useGetEvidence<TData = Awaited<ReturnType<typeof getEvidence>>, TError = ErrorType<unknown>>(
 params?: GetEvidenceParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getEvidence>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetEvidenceQueryOptions(params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







